INSERT INTO support_knowledge (title, body, published) VALUES
  ('Pause and resume subscriptions', 'Open My subscriptions in the customer portal and select Pause. Pausing is available only if your plan allows it and the subscription is Active. Use Resume to reactivate a paused subscription. The next billing date shifts by the number of paused days.', true),
  ('Renew or close a subscription', 'Open My subscriptions to renew an Active subscription when your plan allows renewal and has an expiry date. Renewal extends the term by one billing period. Closing early is available only when your plan allows early close. Contact support if an action is unavailable.', true),
  ('Invoices, payments and overdue balances', 'Open My invoices in the customer portal to see issued invoices and outstanding balances. An invoice is overdue when its due date has passed and it still has an outstanding balance. Staff record payments and the invoice becomes Paid when fully settled. Contact the billing team to arrange payment.', true),
  ('Reset your password', 'Select Forgot password on the login page and enter your account email. Follow the reset link in the email to choose a new password. The link expires after 30 minutes and can be used once. Passwords need at least 9 characters, uppercase and lowercase letters, and a special character.', true);
